/**
 * TTOken Code composer chips: the Session's working folder and the branch its
 * checkout is on in the option row above the draft, and the per-task step limit
 * beside the model below it.
 * Generated by ttoken/apply-brand.mjs from ttoken/client/composer/TtokenChips.tsx; edit it there.
 */
import { useEffect, useState } from 'react'
import type { ReactNode } from 'react'
import type { HostObservable, InjectFace, PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import { IconBranchOutlineRegular, IconChevronDownOutlineRegular, IconFolderCloseRegular, Menu, Tooltip } from '@deepseek-ai/dsh-client-ui-primitives'
import type { MenuEntry } from '@deepseek-ai/dsh-client-ui-primitives'
import type { ConfigFormSnapshot } from '@deepseek-ai/dsh-client-ui-settings/client'
import { pathPartsOf } from '@deepseek-ai/dsh-util-workspace-path'
import type { TTOKEN_COMPOSER_NS } from './locales.ts'
import css from './TtokenChips.module.css'

/** HEAD of the Session's checkout. */
export type GitHead =
  | { readonly kind: 'branch'; readonly name: string }
  | { readonly kind: 'detached'; readonly commit: string }

/** Injected Host read behind the branch chip. */
export interface BranchChipInjected {
  /**
   * Read the checkout's HEAD.
   * @param signal - cancels the read when the chip unmounts or reads again.
   * @returns the branch or detached commit, or null outside a Git checkout or when HEAD cannot be read.
   */
  readHead: (signal: AbortSignal) => Promise<GitHead | null>
}

/** Props shared by the chips: the composer's Session kit and the chip copy. */
export type TtokenChipProps = PropsRuntime<'conversation.input.left'> & PropsLocale<typeof TTOKEN_COMPOSER_NS>

/** Interval between HEAD reads while the chip shows, besides reads on window focus. */
const HEAD_REFRESH_MS = 15_000

/**
 * Working folder chip. Its folder is the directory the Session was created in,
 * else the Workspace that lists it; a press opens that folder's context menu.
 * @param props - Session kit and copy.
 * @returns the chip, or null before the folder is known.
 */
export function FolderChip({ sessionId, useSessions, useWorkspaces, useContextMenu, t }: TtokenChipProps): ReactNode {
  const createdIn = useSessions(snapshot => snapshot.byId[sessionId]?.cwd)
  const workspacePath = useWorkspaces(snapshot => snapshot.items.find(item => item.sessionIds.includes(sessionId))?.path)
  const { getTriggerProps } = useContextMenu()
  const path = createdIn ?? workspacePath
  if (path === undefined) return null
  const trigger = getTriggerProps({ kind: 'directory', value: { sessionId, path } })
  return (
    <Tooltip label={t('folder.title', { path })} side="top" delayMs={500} portal>
      <button type="button" className={css.chip} {...trigger} onClick={(event) => { trigger.onContextMenu?.(event) }}>
        <IconFolderCloseRegular size={16} />
        <span className={css.label}>{pathPartsOf(path).name}</span>
      </button>
    </Tooltip>
  )
}

/**
 * Branch chip: names the checked-out branch, or the short commit of a detached
 * HEAD. It reads HEAD on mount, on window focus, and every {@link HEAD_REFRESH_MS},
 * and renders nothing outside a Git checkout.
 * @param props - Session kit, copy, and the injected HEAD read.
 * @returns the chip, or null without a readable HEAD.
 */
export function BranchChip({ readHead, t }: TtokenChipProps & InjectFace<BranchChipInjected>): ReactNode {
  const [head, setHead] = useState<GitHead | null>(null)
  useEffect(() => {
    let controller = new AbortController()
    const read = (): void => {
      controller.abort()
      controller = new AbortController()
      const { signal } = controller
      void readHead(signal).then((next) => {
        if (!signal.aborted) setHead(next)
      }, (error: unknown) => {
        // A cancelled or failed read hides the chip until the next read succeeds.
        if (!signal.aborted) setHead(null)
        void error
      })
    }
    read()
    const timer = setInterval(read, HEAD_REFRESH_MS)
    window.addEventListener('focus', read)
    return () => {
      controller.abort()
      clearInterval(timer)
      window.removeEventListener('focus', read)
    }
  }, [readHead])
  if (head === null) return null
  return (
    <Tooltip label={head.kind === 'branch' ? t('branch.title') : t('branch.detached', { commit: head.commit })} side="top" delayMs={500} portal>
      <span className={css.chip} data-static="" tabIndex={0}>
        <IconBranchOutlineRegular size={16} />
        <span className={css.label}>{head.kind === 'branch' ? head.name : head.commit}</span>
      </span>
    </Tooltip>
  )
}

/** Settings section of the loop guard that enforces the step limit. */
export interface StepLimitSettings {
  /** Model steps one task may take before the agent stops to ask; 0 turns the limit off. */
  stepLimit?: number
}

/** Injected settings face behind the step limit chip. */
export interface StepLimitChipInjected {
  hooks: {
    /** The loop guard's settings section. */
    stepLimitSettings: HostObservable<ConfigFormSnapshot<StepLimitSettings>>
  }
  /**
   * Write the step limit.
   * @param limit - steps per task, or 0 for no limit.
   * @returns whether the Host accepted the write.
   */
  setStepLimit: (limit: number) => Promise<boolean>
}

/** Step limits the menu offers; 0 is no limit. */
const STEP_LIMITS = [10, 20, 50, 100, 0] as const

/**
 * Step limit chip: names the limit and opens a menu of limits. It renders
 * nothing until the loop guard's settings are ready and writable.
 * @param props - composer kit, copy, the settings hook, and the write.
 * @returns the chip, or null without writable settings.
 */
export function StepLimitChip({
  useStepLimitSettings, setStepLimit, t,
}: PropsRuntime<'conversation.input.right'> & PropsLocale<typeof TTOKEN_COMPOSER_NS> & InjectFace<StepLimitChipInjected>): ReactNode {
  const ready = useStepLimitSettings(snapshot => snapshot.status === 'ready' && snapshot.writable)
  const limit = useStepLimitSettings(snapshot => snapshot.value?.stepLimit)
  const [open, setOpen] = useState(false)
  if (!ready || limit === undefined) return null
  const label = (value: number): string => (value === 0 ? t('steps.off') : t('steps.label', { count: String(value) }))
  const items: MenuEntry[] = [
    { type: 'label', id: 'title', text: t('steps.title') },
    ...STEP_LIMITS.map(value => ({ id: String(value), label: value === 0 ? t('steps.none') : String(value) })),
  ]
  return (
    <Menu
      open={open}
      items={items}
      selectedId={String(limit)}
      onSelect={(id) => {
        setOpen(false)
        void setStepLimit(Number(id))
      }}
      onClose={() => { setOpen(false) }}
      side="top"
      align="end"
      portal
      anchor={
        <button type="button" className={css.steps} aria-haspopup="menu" aria-expanded={open} onClick={() => { setOpen(!open) }}>
          {label(limit)}
          <span className={css.chevron} aria-hidden><IconChevronDownOutlineRegular /></span>
        </button>
      }
    />
  )
}
